def canConvertString(s, t, k):
    if len(s) != len(t):
        return False

    shifts = [0] * 26

    for a, b in zip(s, t):
        diff = (ord(b) - ord(a)) % 26
        if diff > 0:
            shifts[diff] += 1

    for i in range(1, 26):
        if shifts[i] > 0:
            max_shift = (shifts[i] - 1) * 26 + i
            if max_shift > k:
                return False
    return True

# Example usage:
# print(canConvertString("input", "ouput", 9))  # Output: true
# print(canConvertString("abc", "bcd", 10))     # Output: false
# print(canConvertString("aab", "bbb", 27))     # Output: true
